answer_code:
function sameValue(a, b) {
  if (a === b) {
    // +0 と -0 だけがここで区別できない。逆数の符号で見分ける
    return a !== 0 || 1 / a === 1 / b;
  }
  // === が false でも、NaN どうしなら同一とみなす
  return a !== a && b !== b;
}

