answer_code:
const PERM = { READ: 1, WRITE: 2, EXEC: 4, ADMIN: 8 };

function addFlags(mask, ...flags) {
  return flags.reduce((acc, f) => acc | f, mask);
}

function hasAll(mask, flags) {
  return (mask & flags) === flags;
}

function flagNames(mask) {
  return Object.keys(PERM).filter((name) => (mask & PERM[name]) !== 0);
}

