answer_code:
class StringBuilder {
  constructor() {
    this.parts = [];
    this.total = 0;
  }

  push(chunk) {
    this.parts.push(chunk);
    this.total += chunk.length;
    return this;
  }

  get length() {
    return this.total;
  }

  build() {
    return this.parts.join("");
  }

  clear() {
    this.parts = [];
    this.total = 0;
    return this;
  }
}

