answer_code:
function parseUser(text) {
  let raw;
  try {
    raw = JSON.parse(text);
  } catch (e) {
    return { ok: false, error: "JSON として読めません: " + e.message };
  }
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    return { ok: false, error: "オブジェクトではありません" };
  }
  if (typeof raw.name !== "string" || raw.name.length === 0) {
    return { ok: false, error: "name は空でない文字列である必要があります" };
  }
  if (!Number.isInteger(raw.age) || raw.age < 0 || raw.age > 150) {
    return { ok: false, error: "age は 0 以上 150 以下の整数である必要があります" };
  }
  let tags = [];
  if (raw.tags !== undefined) {
    if (!Array.isArray(raw.tags) || !raw.tags.every((t) => typeof t === "string")) {
      return { ok: false, error: "tags は文字列の配列である必要があります" };
    }
    tags = [...raw.tags];
  }
  return { ok: true, value: { name: raw.name, age: raw.age, tags } };
}

