answer_code:
function defineLazy(obj, key, compute) {
  return Object.defineProperty(obj, key, {
    configurable: true,
    enumerable: true,
    get() {
      const value = compute.call(this);
      // 自分自身をデータプロパティに置き換える。以後 getter は呼ばれない
      Object.defineProperty(this, key, {
        value,
        writable: true,
        enumerable: true,
        configurable: true,
      });
      return value;
    },
  });
}

