answer_code:
function copyOnWrite(base) {
  let current = base;
  let copyCount = 0;

  const ensureCopy = () => {
    if (current === base) {
      current = { ...base };
      copyCount += 1;
    }
  };

  const view = new Proxy({}, {
    get(_target, key) {
      return current[key];
    },
    set(_target, key, value) {
      ensureCopy();
      current[key] = value;
      return true;
    },
    has(_target, key) {
      return key in current;
    },
    ownKeys() {
      return Reflect.ownKeys(current);
    },
    getOwnPropertyDescriptor(_target, key) {
      const desc = Object.getOwnPropertyDescriptor(current, key);
      return desc === undefined ? undefined : { ...desc, configurable: true };
    },
    deleteProperty(_target, key) {
      ensureCopy();
      delete current[key];
      return true;
    },
  });

  return { view, copies: () => copyCount };
}

