function Serializable(Base) {
  return class extends Base {
    serialize() {
      return JSON.stringify(this.toObject());
    }
  };
}

function Countable(Base) {
  return class extends Base {
    constructor(...args) {
      super(...args);
      this.count = 0;
    }
    incr() {
      this.count += 1;
      return this.count;
    }
  };
}

function mixinAll(Base, ...mixins) {
  return mixins.reduce((Acc, mix) => mix(Acc), Base);
}

