const counterStates = new WeakMap();

class Counter {
  constructor(start = 0) {
    counterStates.set(this, { value: start });
  }

  get value() {
    return stateOf(this).value;
  }

  increment(by = 1) {
    const state = stateOf(this);
    state.value += by;
    return state.value;
  }
}

function stateOf(self) {
  const state = counterStates.get(self);
  if (state === undefined) {
    throw new TypeError("Counter のインスタンスではありません");
  }
  return state;
}

