function createWeakStore(refFactory = (v) => new WeakRef(v)) {
  const refs = new Map();

  return {
    set(key, obj) {
      if (obj === null || (typeof obj !== "object" && typeof obj !== "function")) {
        throw new TypeError("弱参照で保持できるのはオブジェクトだけです");
      }
      refs.set(key, refFactory(obj));
      return this;
    },
    get(key) {
      const ref = refs.get(key);
      if (ref === undefined) return undefined;
      const value = ref.deref();
      if (value === undefined) {
        refs.delete(key);
        return undefined;
      }
      return value;
    },
    size() {
      return refs.size;
    },
  };
}

