class ResourceTracker {
  constructor(onCleanup) {
    this.onCleanup = onCleanup;
    this.open = new Set();
    this.registry = new FinalizationRegistry((handle) => {
      if (this.open.delete(handle)) {
        this.onCleanup(handle, "gc");
      }
    });
  }

  register(obj, handle) {
    this.open.add(handle);
    this.registry.register(obj, handle, obj);
    return handle;
  }

  close(obj, handle) {
    if (!this.open.delete(handle)) return false;
    this.registry.unregister(obj);
    this.onCleanup(handle, "explicit");
    return true;
  }

  openCount() {
    return this.open.size;
  }
}

