answer_code:
function createTTLCache({ ttlMs, now = Date.now } = {}) {
  if (typeof ttlMs !== "number" || !(ttlMs > 0)) {
    throw new RangeError("ttlMs は正の数である必要があります");
  }
  const entries = new Map();
  const isExpired = (entry, at) => entry.expiresAt <= at;

  return {
    set(key, value) {
      entries.set(key, { value, expiresAt: now() + ttlMs });
      return this;
    },
    get(key) {
      const entry = entries.get(key);
      if (entry === undefined) return undefined;
      if (isExpired(entry, now())) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },
    prune() {
      const at = now();
      let removed = 0;
      for (const [key, entry] of entries) {
        if (isExpired(entry, at)) {
          entries.delete(key);
          removed += 1;
        }
      }
      return removed;
    },
    size() {
      return entries.size;
    },
  };
}

