answer_code:
class Trie {
  constructor() {
    this.root = { children: new Map(), end: false };
    this.count = 0;
  }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      let next = node.children.get(ch);
      if (next === undefined) {
        next = { children: new Map(), end: false };
        node.children.set(ch, next);
      }
      node = next;
    }
    if (node.end) return false;
    node.end = true;
    this.count += 1;
    return true;
  }

  walk(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      node = node.children.get(ch);
      if (node === undefined) return null;
    }
    return node;
  }

  has(word) {
    const node = this.walk(word);
    return node !== null && node.end;
  }

  startsWith(prefix) {
    return this.walk(prefix) !== null;
  }

  wordsWithPrefix(prefix) {
    const start = this.walk(prefix);
    const found = [];
    if (start === null) return found;
    const visit = (node, acc) => {
      if (node.end) found.push(acc);
      for (const [ch, child] of node.children) visit(child, acc + ch);
    };
    visit(start, prefix);
    return found.sort();
  }
}

