class DSU {
  constructor(n) {
    if (!Number.isInteger(n) || n < 1) {
      throw new RangeError("n は 1 以上の整数である必要があります");
    }
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank = new Array(n).fill(0);
    this.sizes = new Array(n).fill(1);
    this.groups = n;
  }

  find(x) {
    let root = x;
    while (this.parent[root] !== root) root = this.parent[root];
    while (this.parent[x] !== root) {
      const next = this.parent[x];
      this.parent[x] = root;
      x = next;
    }
    return root;
  }

  union(a, b) {
    let ra = this.find(a);
    let rb = this.find(b);
    if (ra === rb) return false;
    if (this.rank[ra] < this.rank[rb]) {
      const tmp = ra;
      ra = rb;
      rb = tmp;
    }
    this.parent[rb] = ra;
    this.sizes[ra] += this.sizes[rb];
    if (this.rank[ra] === this.rank[rb]) this.rank[ra] += 1;
    this.groups -= 1;
    return true;
  }

  connected(a, b) {
    return this.find(a) === this.find(b);
  }

  size(x) {
    return this.sizes[this.find(x)];
  }

  count() {
    return this.groups;
  }
}

