answer_code:
class BitSet {
  constructor(size) {
    if (!Number.isInteger(size) || size < 0) {
      throw new RangeError("size は 0 以上の整数である必要があります");
    }
    this.size = size;
    this.words = new Uint32Array(Math.ceil(size / 32));
  }

  assertIndex(i) {
    if (!Number.isInteger(i) || i < 0 || i >= this.size) {
      throw new RangeError("範囲外の添字です: " + i);
    }
  }

  add(i) {
    this.assertIndex(i);
    this.words[i >>> 5] |= 1 << (i & 31);
    return this;
  }

  delete(i) {
    this.assertIndex(i);
    this.words[i >>> 5] &= ~(1 << (i & 31));
    return this;
  }

  has(i) {
    this.assertIndex(i);
    return (this.words[i >>> 5] & (1 << (i & 31))) !== 0;
  }

  count() {
    let total = 0;
    for (const word of this.words) {
      let w = word;
      while (w !== 0) {
        w &= w - 1;
        total += 1;
      }
    }
    return total;
  }

  combine(other, op) {
    if (!(other instanceof BitSet) || other.size !== this.size) {
      throw new TypeError("同じサイズの BitSet が必要です");
    }
    const out = new BitSet(this.size);
    for (let w = 0; w < this.words.length; w += 1) {
      out.words[w] = op(this.words[w], other.words[w]);
    }
    return out;
  }

  and(other) {
    return this.combine(other, (x, y) => x & y);
  }

  or(other) {
    return this.combine(other, (x, y) => x | y);
  }

  toArray() {
    const out = [];
    for (let i = 0; i < this.size; i += 1) {
      if (this.has(i)) out.push(i);
    }
    return out;
  }
}

