answer_code:
function quickselect(arr, k, rng = Math.random) {
  if (!Array.isArray(arr)) {
    throw new TypeError("配列を渡してください");
  }
  if (!Number.isInteger(k) || k < 0 || k >= arr.length) {
    throw new RangeError("k が範囲外です");
  }

  const a = arr.slice();
  let lo = 0;
  let hi = a.length - 1;

  while (lo < hi) {
    const p = lo + Math.floor(rng() * (hi - lo + 1));
    const pivot = a[p];
    a[p] = a[hi];
    a[hi] = pivot;

    let store = lo;
    for (let i = lo; i < hi; i += 1) {
      if (a[i] < pivot) {
        const tmp = a[i];
        a[i] = a[store];
        a[store] = tmp;
        store += 1;
      }
    }
    a[hi] = a[store];
    a[store] = pivot;

    if (k === store) return a[store];
    if (k < store) hi = store - 1;
    else lo = store + 1;
  }

  return a[lo];
}

