answer_code:
function toColumnar(rows) {
  const names = [];
  for (const row of rows) {
    for (const key of Object.keys(row)) {
      if (!names.includes(key)) names.push(key);
    }
  }

  const columns = {};
  for (const name of names) {
    columns[name] = new Array(rows.length).fill(null);
  }
  rows.forEach((row, i) => {
    for (const name of names) {
      if (Object.prototype.hasOwnProperty.call(row, name)) {
        columns[name][i] = row[name];
      }
    }
  });

  return { length: rows.length, columns };
}

function fromColumnar(table) {
  const names = Object.keys(table.columns);
  const rows = [];
  for (let i = 0; i < table.length; i += 1) {
    const row = {};
    for (const name of names) {
      row[name] = table.columns[name][i];
    }
    rows.push(row);
  }
  return rows;
}

function sumColumn(table, name) {
  const column = table.columns[name];
  if (column === undefined) {
    throw new Error("列がありません: " + name);
  }
  let total = 0;
  for (const value of column) {
    if (typeof value === "number") total += value;
  }
  return total;
}

