answer_code:
class Heap {
  constructor(compare) {
    this.compare = compare;
    this.items = [];
  }

  get size() { return this.items.length; }
  peek() { return this.items[0]; }

  push(value) {
    const a = this.items;
    a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.compare(a[i], a[parent]) >= 0) break;
      const tmp = a[i];
      a[i] = a[parent];
      a[parent] = tmp;
      i = parent;
    }
  }

  pop() {
    const a = this.items;
    const top = a[0];
    const last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let best = i;
        if (left < a.length && this.compare(a[left], a[best]) < 0) best = left;
        if (right < a.length && this.compare(a[right], a[best]) < 0) best = right;
        if (best === i) break;
        const tmp = a[i];
        a[i] = a[best];
        a[best] = tmp;
        i = best;
      }
    }
    return top;
  }
}

class RunningMedian {
  constructor() {
    this.low = new Heap((a, b) => b - a);
    this.high = new Heap((a, b) => a - b);
  }

  add(x) {
    if (typeof x !== "number" || Number.isNaN(x)) {
      throw new TypeError("数値を渡してください");
    }
    if (this.low.size === 0 || x <= this.low.peek()) this.low.push(x);
    else this.high.push(x);

    if (this.low.size > this.high.size + 1) this.high.push(this.low.pop());
    else if (this.high.size > this.low.size) this.low.push(this.high.pop());
    return this;
  }

  get size() {
    return this.low.size + this.high.size;
  }

  median() {
    if (this.size === 0) return null;
    if (this.low.size > this.high.size) return this.low.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}

