answer_code:
function addCPS(a, b, k) {
  k(a + b);
}

function factCPS(n, k) {
  if (n < 0) {
    throw new RangeError("n は 0 以上である必要があります");
  }
  if (n === 0) {
    k(1);
    return;
  }
  factCPS(n - 1, (rest) => k(rest * n));
}

function mapCPS(arr, fCPS, k) {
  const out = [];
  const step = (i) => {
    if (i === arr.length) {
      k(out);
      return;
    }
    fCPS(arr[i], (value) => {
      out.push(value);
      step(i + 1);
    });
  };
  step(0);
}

