answer_code:
function mapping(f) {
  return (step) => (acc, x) => step(acc, f(x));
}

function filtering(pred) {
  return (step) => (acc, x) => (pred(x) ? step(acc, x) : acc);
}

function compose(...xfs) {
  return (step) => xfs.reduceRight((next, xf) => xf(next), step);
}

function transduce(xf, step, init, coll) {
  const reducer = xf(step);
  let acc = init;
  for (const x of coll) {
    acc = reducer(acc, x);
  }
  return acc;
}

