function* naturals(start = 1) {
  let n = start;
  for (;;) {
    yield n;
    n += 1;
  }
}

function lazyMap(f) {
  return function* (source) {
    for (const x of source) yield f(x);
  };
}

function lazyFilter(pred) {
  return function* (source) {
    for (const x of source) {
      if (pred(x)) yield x;
    }
  };
}

function take(n) {
  return function* (source) {
    if (n <= 0) return;
    let taken = 0;
    for (const x of source) {
      yield x;
      taken += 1;
      if (taken >= n) return;
    }
  };
}

function pipe(source, ...stages) {
  return stages.reduce((current, stage) => stage(current), source);
}

function toArray(iterable) {
  return [...iterable];
}

