answer_code:
function runAsync(genFn, ...args) {
  return new Promise((resolve, reject) => {
    const gen = genFn(...args);
    function step(method, arg) {
      let res;
      try {
        res = gen[method](arg);
      } catch (e) {
        reject(e);
        return;
      }
      if (res.done) {
        resolve(res.value);
        return;
      }
      Promise.resolve(res.value).then(
        (v) => step("next", v),
        (e) => step("throw", e)
      );
    }
    step("next", undefined);
  });
}

