answer_code:
function emptyList() {
  return null;
}

function cons(list, value) {
  return { value, next: list, size: (list === null ? 0 : list.size) + 1 };
}

function listSize(list) {
  return list === null ? 0 : list.size;
}

function toArray(list) {
  const out = [];
  for (let node = list; node !== null; node = node.next) {
    out.push(node.value);
  }
  return out;
}

