function setIn(target, path, value) {
  if (path.length === 0) return value;
  const [key, ...rest] = path;
  const copy = Array.isArray(target) ? target.slice() : { ...target };
  const child = target === null || target === undefined ? undefined : target[key];
  copy[key] = setIn(child, rest, value);
  return copy;
}

