const isNumber = (v) => (typeof v === "number" ? null : "数値である必要があります");

const schema = { name: [notEmpty, minLen3], age: [isNumber] };

validate(schema, { name: "taro", age: 20 });
// => { ok: true, value: { name: "taro", age: 20 } }

validate(schema, { name: "", age: "x" });
// => { ok: false, errors: ["name: 必須です", "name: 3文字以上", "age: 数値である必要があります"] }
```

