function str(s) {
  return (input, pos) =>
    input.startsWith(s, pos)
      ? { ok: true, value: s, pos: pos + s.length }
      : { ok: false, pos };
}

function seq(...ps) {
  return (input, pos) => {
    const values = [];
    let cur = pos;
    for (const p of ps) {
      const r = p(input, cur);
      if (!r.ok) return { ok: false, pos };
      values.push(r.value);
      cur = r.pos;
    }
    return { ok: true, value: values, pos: cur };
  };
}

function alt(...ps) {
  return (input, pos) => {
    for (const p of ps) {
      const r = p(input, pos);
      if (r.ok) return r;
    }
    return { ok: false, pos };
  };
}

function many(p) {
  return (input, pos) => {
    const values = [];
    let cur = pos;
    for (;;) {
      const r = p(input, cur);
      if (!r.ok || r.pos === cur) break;
      values.push(r.value);
      cur = r.pos;
    }
    return { ok: true, value: values, pos: cur };
  };
}

function run(p, input) {
  const r = p(input, 0);
  return r.ok && r.pos === input.length ? r.value : null;
}

