function tokenize(src) {
  const out = [];
  const re = /\s*(\d+|[()+\-*\/])/g;
  let m;
  while ((m = re.exec(src)) !== null) out.push(m[1]);
  return out;
}

function evalExpr(src) {
  const tokens = tokenize(src);
  let i = 0;

  function eat(t) {
    if (tokens[i] === t) { i++; return true; }
    return false;
  }

  function parseFactor() {
    if (eat("(")) {
      const v = parseExpr();
      eat(")");
      return v;
    }
    return Number(tokens[i++]);
  }

  function parseTerm() {
    let v = parseFactor();
    for (;;) {
      if (eat("*")) v = v * parseFactor();
      else if (eat("/")) v = v / parseFactor();
      else return v;
    }
  }

  function parseExpr() {
    let v = parseTerm();
    for (;;) {
      if (eat("+")) v = v + parseTerm();
      else if (eat("-")) v = v - parseTerm();
      else return v;
    }
  }

  return parseExpr();
}

