answer_code:
function createHooks() {
  const registry = new Map();
  let seq = 0;
  return {
    on(name, fn, priority = 0) {
      if (!registry.has(name)) registry.set(name, []);
      registry.get(name).push({ fn, priority, seq: seq++ });
      return this;
    },
    run(name, arg) {
      const handlers = (registry.get(name) || [])
        .slice()
        .sort((x, y) => x.priority - y.priority || x.seq - y.seq);
      const results = [];
      const errors = [];
      for (const h of handlers) {
        try {
          results.push(h.fn(arg));
        } catch (e) {
          errors.push(e.message);
        }
      }
      return { results, errors };
    },
  };
}

