answer_code:
function createContainer() {
  const defs = new Map();
  const cache = new Map();
  const building = [];

  function resolve(name) {
    if (cache.has(name)) return cache.get(name);
    if (building.indexOf(name) >= 0) {
      throw new Error("circular dependency: " + building.concat(name).join(" -> "));
    }
    if (!defs.has(name)) throw new Error("unknown service: " + name);
    const def = defs.get(name);
    building.push(name);
    try {
      const args = def.deps.map((d) => resolve(d));
      const instance = def.factory(...args);
      cache.set(name, instance);
      return instance;
    } finally {
      building.pop();
    }
  }

  return {
    register(name, deps, factory) {
      defs.set(name, { deps, factory });
      return this;
    },
    resolve,
  };
}

