answer_code:
function query(state) {
  const s = state || { cols: [], table: null, conds: [], limit: null };
  const next = (patch) => query({ ...s, ...patch });
  return {
    select(...cols) {
      return next({ cols: s.cols.concat(cols) });
    },
    from(table) {
      return next({ table });
    },
    where(cond) {
      return next({ conds: s.conds.concat([cond]) });
    },
    limit(n) {
      return next({ limit: n });
    },
    build() {
      const cols = s.cols.length > 0 ? s.cols.join(", ") : "*";
      let out = "SELECT " + cols + " FROM " + s.table;
      if (s.conds.length > 0) out += " WHERE " + s.conds.join(" AND ");
      if (s.limit !== null) out += " LIMIT " + s.limit;
      return out;
    },
  };
}

