let activeEffect = null;

function signal(initial) {
  let value = initial;
  const subscribers = new Set();
  return {
    get() {
      if (activeEffect !== null) subscribers.add(activeEffect);
      return value;
    },
    set(v) {
      value = v;
      for (const run of Array.from(subscribers)) run();
    },
  };
}

function effect(fn) {
  const run = () => {
    const prev = activeEffect;
    activeEffect = run;
    try {
      fn();
    } finally {
      activeEffect = prev;
    }
  };
  run();
}

