answer_code:
function diffKeys(oldList, newList) {
  const oldKeys = oldList.map((n) => n.key);
  const newKeys = newList.map((n) => n.key);
  const oldSet = new Set(oldKeys);
  const newSet = new Set(newKeys);

  const inserted = newKeys.filter((k) => !oldSet.has(k));
  const removed = oldKeys.filter((k) => !newSet.has(k));

  const oldCommon = oldKeys.filter((k) => newSet.has(k));
  const newCommon = newKeys.filter((k) => oldSet.has(k));
  const moved = newCommon.filter((k) => oldCommon.indexOf(k) !== newCommon.indexOf(k));

  return { inserted, removed, moved };
}

