answer_code:
function structuralKey(value) {
  if (value === null) return "null";
  const t = typeof value;
  if (t === "undefined") return "undefined";
  if (t === "number" || t === "boolean") return t + ":" + String(value);
  if (t === "string") return "s:" + JSON.stringify(value);
  if (Array.isArray(value)) return "[" + value.map(structuralKey).join(",") + "]";
  if (t === "object") {
    const keys = Object.keys(value).sort();
    return "{" + keys.map((k) => JSON.stringify(k) + ":" + structuralKey(value[k])).join(",") + "}";
  }
  return t + ":" + String(value);
}

function dedupe(values) {
  const seen = new Set();
  const out = [];
  for (const v of values) {
    const key = structuralKey(v);
    if (!seen.has(key)) {
      seen.add(key);
      out.push(v);
    }
  }
  return out;
}

