function sumInChunks(numbers, chunkSize) {
  return new Promise((resolve) => {
    let index = 0;
    let total = 0;
    const step = () => {
      const end = Math.min(index + chunkSize, numbers.length);
      for (; index < end; index++) {
        total += numbers[index];
      }
      if (index < numbers.length) {
        setTimeout(step, 0);
      } else {
        resolve(total);
      }
    };
    step();
  });
}

