async function runSteps(steps, signal) {
  const throwIfAborted = () => {
    if (signal && signal.aborted) throw signal.reason;
  };
  const results = [];
  for (const step of steps) {
    throwIfAborted();
    results.push(await step(signal));
  }
  throwIfAborted();
  return results;
}

