answer_code:
function createSemaphore(limit) {
  let inUse = 0;
  const waiters = [];

  function makeRelease() {
    let released = false;
    return () => {
      if (released) return;
      released = true;
      const next = waiters.shift();
      if (next) next(makeRelease()); // 枠はそのまま次の人へ譲る
      else inUse--;
    };
  }

  return {
    acquire() {
      if (inUse < limit) {
        inUse++;
        return Promise.resolve(makeRelease());
      }
      return new Promise((resolve) => waiters.push(resolve));
    },
    active() {
      return inUse;
    },
  };
}

