answer_code:
function createTokenBucket({ capacity, refillPerMs, now }) {
  let tokens = capacity;
  let last = now();

  const refill = () => {
    const current = now();
    const gained = (current - last) * refillPerMs;
    if (gained > 0) {
      tokens = Math.min(capacity, tokens + gained);
      last = current;
    }
  };

  return {
    tryTake(n) {
      refill();
      if (tokens >= n) {
        tokens -= n;
        return true;
      }
      return false;
    },
    waitMs(n) {
      refill();
      if (tokens >= n) return 0;
      if (n > capacity) return Infinity;
      return Math.ceil((n - tokens) / refillPerMs);
    },
    tokens() {
      refill();
      return tokens;
    },
  };
}

