answer_code:
function createBreaker({ failureThreshold, cooldownMs, now }) {
  let state = "closed";
  let failures = 0;
  let openedAt = 0;

  const trip = () => {
    state = "open";
    openedAt = now();
    failures = 0;
  };

  return {
    state() {
      if (state === "open" && now() - openedAt >= cooldownMs) return "half-open";
      return state;
    },
    async call(fn) {
      if (state === "open") {
        if (now() - openedAt < cooldownMs) throw new Error("circuit open");
        state = "half-open";
      }
      const wasHalfOpen = state === "half-open";
      try {
        const value = await fn();
        state = "closed";
        failures = 0;
        return value;
      } catch (e) {
        if (wasHalfOpen) {
          trip();
        } else {
          failures++;
          if (failures >= failureThreshold) trip();
        }
        throw e;
      }
    },
  };
}

