answer_code:
async function retry(fn, { retries, baseMs, maxMs, random, sleep }) {
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (e) {
      lastError = e;
      if (attempt === retries) break;
      const cap = Math.min(maxMs, baseMs * Math.pow(2, attempt));
      await sleep(Math.floor(random() * cap));
    }
  }
  throw lastError;
}

