function createSingleFlight(loader) {
  const inflight = new Map();

  return {
    get(key) {
      const running = inflight.get(key);
      if (running) return running;

      const started = Promise.resolve()
        .then(() => loader(key))
        .finally(() => {
          inflight.delete(key);
        });
      inflight.set(key, started);
      return started;
    },
    size() {
      return inflight.size;
    },
  };
}

