answer_code:
function createChannel(capacity) {
  const buffer = [];
  const takers = [];  // 値を待っている take の resolve
  const pushers = []; // 空きを待っている push の続き

  return {
    push(value) {
      const taker = takers.shift();
      if (taker) {
        taker(value); // 待っている人がいれば直接渡す
        return Promise.resolve();
      }
      if (buffer.length < capacity) {
        buffer.push(value);
        return Promise.resolve();
      }
      return new Promise((resolve) => {
        pushers.push(() => {
          buffer.push(value);
          resolve();
        });
      });
    },
    take() {
      if (buffer.length > 0) {
        const value = buffer.shift();
        const pusher = pushers.shift();
        if (pusher) pusher(); // 空いた枠に待たせていた値を入れる
        return Promise.resolve(value);
      }
      return new Promise((resolve) => takers.push(resolve));
    },
    size() {
      return buffer.length;
    },
  };
}

