answer_code:
function firstResult(tasks) {
  const controller = new AbortController();
  return new Promise((resolve, reject) => {
    if (tasks.length === 0) {
      reject(new Error("no tasks"));
      return;
    }
    let settled = false;
    let pending = tasks.length;

    for (const task of tasks) {
      Promise.resolve()
        .then(() => task(controller.signal))
        .then(
          (value) => {
            if (settled) return; // 遅れて来た成功は捨てる
            settled = true;
            controller.abort();
            resolve(value);
          },
          (error) => {
            pending--;
            if (settled) return; // 負けた側の失敗は握りつぶす
            if (pending === 0) {
              settled = true;
              controller.abort();
              reject(error);
            }
          },
        );
    }
  });
}

