answer_code:
class LineSplitter {
  constructor() {
    this.buf = "";
  }

  push(chunk) {
    this.buf += chunk;
    const parts = this.buf.split("\n");
    this.buf = parts.pop(); // 最後の要素は「改行で閉じていない残り」
    return parts;
  }

  flush() {
    if (this.buf === "") return [];
    const rest = this.buf;
    this.buf = "";
    return [rest];
  }
}

