const { Worker } = require("worker_threads");

const WORKER_SRC = `
  const { parentPort, workerData } = require("worker_threads");
  let total = 0;
  for (const n of workerData) total += n;
  parentPort.postMessage(total);
`;

function runChunk(chunk) {
  return new Promise((resolve, reject) => {
    const w = new Worker(WORKER_SRC, { eval: true, workerData: chunk });
    w.on("message", resolve);
    w.on("error", reject);
  });
}

async function sumInWorkers(numbers, workerCount) {
  if (numbers.length === 0) return 0;
  const n = Math.max(1, Math.min(workerCount, numbers.length));
  const size = Math.ceil(numbers.length / n);
  const chunks = [];
  for (let i = 0; i < numbers.length; i += size) {
    chunks.push(numbers.slice(i, i + size));
  }
  const parts = await Promise.all(chunks.map(runChunk));
  return parts.reduce((a, b) => a + b, 0);
}

