const { Worker } = require("worker_threads");

const WORKER_SRC = `
  const { parentPort, workerData } = require("worker_threads");
  const arr = new Int32Array(workerData.sab);
  for (let i = 0; i < workerData.times; i++) {
    Atomics.add(arr, 0, 1);
  }
  parentPort.postMessage("done");
`;

function countUp(workerCount, timesPerWorker) {
  const sab = new SharedArrayBuffer(4);
  const arr = new Int32Array(sab);
  const jobs = [];
  for (let i = 0; i < workerCount; i++) {
    jobs.push(new Promise((resolve, reject) => {
      const w = new Worker(WORKER_SRC, {
        eval: true,
        workerData: { sab, times: timesPerWorker },
      });
      w.on("message", resolve);
      w.on("error", reject);
    }));
  }
  return Promise.all(jobs).then(() => Atomics.load(arr, 0));
}

