answer_code:
function measure(fn, options) {
  const { warmup = 0, iterations = 1 } = options || {};
  if (!Number.isInteger(iterations) || iterations < 1) {
    throw new RangeError("iterations は 1 以上の整数である必要があります: " + iterations);
  }

  for (let i = 0; i < warmup; i++) {
    fn();
  }

  let result;
  const start = process.hrtime.bigint();
  for (let i = 0; i < iterations; i++) {
    result = fn(); // 戻り値を保持して「呼んだだけ」で消えないようにする
  }
  const end = process.hrtime.bigint();

  const totalMs = Number(end - start) / 1e6;
  return { iterations, totalMs, meanMs: totalMs / iterations, result };
}

