answer_code:
function sortHumanly(names) {
  const collator = new Intl.Collator("ja", {
    numeric: true,       // 文字列中の数字を数値として比較する
    sensitivity: "base", // 大小文字・アクセントの違いを無視する
  });
  return [...names].sort(collator.compare);
}

