const __segmenter = new Intl.Segmenter("ja", { granularity: "grapheme" });

function graphemeLength(str) {
  let n = 0;
  for (const _ of __segmenter.segment(str)) n++;
  return n;
}

function truncateGraphemes(str, max) {
  if (max <= 0) return "";
  let out = "";
  let n = 0;
  for (const { segment } of __segmenter.segment(str)) {
    if (n >= max) break;
    out += segment;
    n++;
  }
  return out;
}

