answer_code:
function encode(value) {
  return JSON.stringify(value, (key, v) => {
    if (v instanceof Map) return { $type: "Map", value: [...v] };
    if (v instanceof Set) return { $type: "Set", value: [...v] };
    return v;
  });
}

function decode(text) {
  return JSON.parse(text, (key, v) => {
    if (v !== null && typeof v === "object" && !Array.isArray(v)) {
      if (v.$type === "Map") return new Map(v.value);
      if (v.$type === "Set") return new Set(v.value);
    }
    return v;
  });
}

