answer_code:
function serialize(root) {
  const nodes = [];
  const ids = new Map(); // オブジェクト -> id

  function idOf(obj) {
    if (ids.has(obj)) return ids.get(obj);
    const id = nodes.length;
    ids.set(obj, id);      // 中身を詰める前に登録する (これが循環を止める)
    nodes.push(null);
    const body = Array.isArray(obj) ? [] : {};
    nodes[id] = { type: Array.isArray(obj) ? "array" : "object", body };
    for (const key of Object.keys(obj)) body[key] = cell(obj[key]);
    return id;
  }

  function cell(v) {
    if (v !== null && typeof v === "object") return { $ref: idOf(v) };
    return { $val: v };
  }

  return JSON.stringify({ root: cell(root), nodes });
}

function deserialize(text) {
  const data = JSON.parse(text);
  // 1. 空の入れ物だけを先に全部作る
  const objs = data.nodes.map((n) => (n.type === "array" ? [] : {}));

  const read = (c) => ("$ref" in c ? objs[c.$ref] : c.$val);

  // 2. そのあとで中身を埋める (このとき参照先はもう存在している)
  data.nodes.forEach((n, i) => {
    for (const key of Object.keys(n.body)) objs[i][key] = read(n.body[key]);
  });

  return read(data.root);
}

description_md:
短命なオブジェクトを大量に作る処理のために、**オブジェクトプール** `createVectorPool()` を作りましょう。返すのは次の 3 つを持つオブジェクトです。

- `acquire(x, y)` … ベクトル `{ x, y }` を返す。返却済みのものがあれば**それを再利用**し、無ければ新規作成する
- `release(v)` … 使い終わったベクトルをプールに戻す。同じものを 2 回戻しても二重登録しない
- `stats()` … `{ created, reused, free }` を返す (新規作成した数 / 再利用した数 / 今プールにある数)

```javascript
const pool = createVectorPool();
const a = pool.acquire(1, 2);
pool.release(a);
const b = pool.acquire(3, 4);
b === a;        // => true  ← 同じオブジェクトが返る
b.x;            // => 3     ← 値は更新されている
pool.stats();   // => { created: 1, reused: 1, free: 0 }
```

