answer_code:
function createVectorPool() {
  const free = [];
  const inFree = new Set(); // 二重返却を弾くための在庫台帳
  let created = 0;
  let reused = 0;

  return {
    acquire(x, y) {
      let v;
      if (free.length > 0) {
        v = free.pop();
        inFree.delete(v);
        reused++;
      } else {
        v = { x: 0, y: 0 };
        created++;
      }
      v.x = x;
      v.y = y;
      return v;
    },

    release(v) {
      if (inFree.has(v)) return; // 既に返却済みなら何もしない
      inFree.add(v);
      free.push(v);
    },

    stats() {
      return { created, reused, free: free.length };
    },
  };
}

