answer_code:
function* chunked(iterable, size) {
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError("size は 1 以上の整数である必要があります: " + size);
  }

  let buf = [];
  for (const item of iterable) {
    buf.push(item);
    if (buf.length === size) {
      yield buf;
      buf = []; // 使い回さず、新しい配列に置き換える
    }
  }
  if (buf.length > 0) yield buf; // 端数
}

