function makePoint(x, y, label = null) {
  // キーの順序も個数も、この 1 か所で固定する
  return { x, y, label };
}

function normalizePoint(raw) {
  const src = raw || {};
  return makePoint(
    src.x === undefined ? 0 : src.x,
    src.y === undefined ? 0 : src.y,
    src.label === undefined ? null : src.label
  );
}

