answer_code:
function sumTree(node) {
  let total = 0;
  const stack = [node]; // 「これから処理するノード」を自分で持つ

  while (stack.length > 0) {
    const cur = stack.pop();
    total += cur.value;
    for (const child of cur.children) {
      stack.push(child);
    }
  }

  return total;
}

