answer_code:
function createScheduler() {
  const waiting = []; // { name, priority, addedAt, seq }
  let tick = 0;
  let seq = 0;

  return {
    add(name, priority) {
      waiting.push({ name, priority, addedAt: tick, seq: seq++ });
    },

    next() {
      if (waiting.length === 0) return null;

      let bestIndex = 0;
      let bestScore = -Infinity;
      for (let i = 0; i < waiting.length; i++) {
        const t = waiting[i];
        const score = t.priority + (tick - t.addedAt); // 実効優先度
        // 同点なら登録が早いほう (seq が小さいほう) を選ぶ
        if (score > bestScore || (score === bestScore && t.seq < waiting[bestIndex].seq)) {
          bestScore = score;
          bestIndex = i;
        }
      }

      const chosen = waiting.splice(bestIndex, 1)[0];
      tick++;
      return chosen.name;
    },
  };
}

