answer_code:
function createHistory(initial) {
  const snapshots = [initial]; // 過去から未来へ並ぶ不変スナップショット
  let index = 0;               // 「現在」がどこか

  return {
    get() {
      return snapshots[index];
    },

    update(patch) {
      const next = { ...snapshots[index], ...patch }; // 浅いコピー = 構造共有
      snapshots.length = index + 1;                   // 未来 (redo 分) を捨てる
      snapshots.push(next);
      index = snapshots.length - 1;
      return next;
    },

    undo() {
      if (index > 0) index--;
      return snapshots[index];
    },

    redo() {
      if (index < snapshots.length - 1) index++;
      return snapshots[index];
    },

    canUndo() {
      return index > 0;
    },

    canRedo() {
      return index < snapshots.length - 1;
    },
  };
}

