answer_code:
function run(program, maxSteps = 10000) {
  const stack = [];
  const output = [];
  let pc = 0;
  let steps = 0;
  let halted = false;

  while (pc >= 0 && pc < program.length) {
    if (steps >= maxSteps) return { stack, output, steps, halted: false };
    const [op, arg] = program[pc];
    pc++;      // 既定は「次の命令」。ジャンプ命令だけがこれを上書きする
    steps++;

    switch (op) {
      case "push": stack.push(arg); break;
      case "add": { const b = stack.pop(); const a = stack.pop(); stack.push(a + b); break; }
      case "sub": { const b = stack.pop(); const a = stack.pop(); stack.push(a - b); break; }
      case "mul": { const b = stack.pop(); const a = stack.pop(); stack.push(a * b); break; }
      case "dup": stack.push(stack[stack.length - 1]); break;
      case "out": output.push(stack.pop()); break;
      case "jmp": pc = arg; break;
      case "jz": if (stack.pop() === 0) pc = arg; break;
      case "halt": halted = true; break;
      default: throw new Error("未知の命令: " + op);
    }
    if (halted) return { stack, output, steps, halted: true };
  }

  return { stack, output, steps, halted: true };
}
